      "attributes": [
        "Resource"
      ]
    },
    {
      "name": "Delivery",
      "description": "Movement of product batches to a recipient",
      "attributes": [
        "Product Batch"
      ]
    },
    {
      "name": "Procurement Officer",
      "description": "Person handling sourcing and supplier negotiations"
    },
    {
      "name": "Supply Order",
      "description": "Order placed to acquire needed materials"
    },
    {
      "name": "Supplier",
      "description": "External provider of crude oil or other feedstocks"
    },
    {
      "name": "Performance Evaluation",
      "description": "Assessment of supplier reliability and cost efficiency"
    },
    {
      "name": "Client",
      "description": "Person interested in buying refinery products"
